// Generated by vibelang from src/routes/stats-cache.ts; the migrate flow writes it again with each batch.
import { LOCALE_HEADER } from "../lib/language.js";
// Stats change throughout the day; expired snapshots must refresh before reuse.
export const statsPageCacheControl = "public, max-age=60, s-maxage=300, must-revalidate";
export function setStatsPageCacheHeaders(headers) {
    if (!headers)
        return;
    headers.set("Cache-Control", statsPageCacheControl);
    // The same URL serves Markdown to clients that ask for it.
    appendVary(headers, "Accept", "Accept-Language", "Cookie", LOCALE_HEADER);
}
function appendVary(headers, ...values) {
    const existing = headers
        .get("vary")
        ?.split(",")
        .map((value) => value.trim())
        .filter(Boolean);
    headers.set("vary", values
        .reduce((result, value) => result.some((item) => item.toLowerCase() === value.toLowerCase()) ? result : [...result, value], existing ?? [])
        .join(", "));
}
